mapper.select:
SELECT 
FROM agent_conversation_turn t
JOIN agent_conversation c ON c.id = t.conversation_id AND c.tenant_id = t.tenant_id
WHERE t.tenant_id = #{tenantId}
  AND c.tenant_id = #{tenantId}
  AND c.executor_id = #{executorId}
  AND t.direction = 'IN'
  AND t.status = 'PROCESSING'
  AND (t.last_dispatch_at <= #{cutoff}
    OR (t.last_dispatch_at IS NULL AND t.gmt_create <= #{cutoff}))
ORDER BY COALESCE(t.last_dispatch_at, t.gmt_create) ASC, t.id ASC
LIMIT #{limit}

mapper.update:
UPDATE agent_conversation_turn
SET status = #{status}, error = #{error}
WHERE tenant_id = #{tenantId} AND id = #{id}

UPDATE agent_conversation_turn
SET status = #{status}, error = #{error}
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND id = #{id}
  AND direction = 'IN'
  AND status = 'PROCESSING'

UPDATE agent_conversation_turn
SET status = #{toStatus}, error = #{error}
WHERE tenant_id = #{tenantId} AND id = #{id} AND status = #{fromStatus}

UPDATE agent_conversation_turn
SET last_dispatch_at = NOW(),
    dispatch_attempt = dispatch_attempt + 1
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND id = #{id}
  AND direction = 'IN'
  AND status = 'PROCESSING'

UPDATE agent_conversation_turn
SET last_dispatch_at = NOW(),
    dispatch_attempt = dispatch_attempt + 1
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND id = #{id}
  AND direction = 'IN'
  AND status = 'PROCESSING'
  AND (last_dispatch_at <= #{cutoff}
    OR (last_dispatch_at IS NULL AND gmt_create <= #{cutoff}))

